using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Expenses.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Expenses.Queries.GetExpenseById;public sealed class GetExpenseByIdQueryHandler(IExpenseRepository repository):IRequestHandler<GetExpenseByIdQuery,Result<ExpenseDto>>{public async Task<Result<ExpenseDto>>Handle(GetExpenseByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<ExpenseDto>(ExpenseErrors.NotFound):Result.Success(ExpenseDto.FromEntity(e));}}
